def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        use_count = Counter()

        def wrapper(*args, **kwargs):
            if typed:
                key = MagicKey(args, kwargs)
            else:
                key = args
            if key in cache:
                use_count[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            use_count[key] = 1
            while len(cache) > maxsize:
                for k, _ in use_count.most_common(1):
                    if k in cache:
                        cache.pop(k)
                        use_count.pop(k)
                        break
            return result
        return wrapper
    return decorator
