def validate_fixity(self, fixity: dict, manifest_files: set) -> None:
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        for algorithm, fixity_info in fixity.items():
            if not isinstance(algorithm, str):
                raise ValueError("Fixity algorithm name must be a string")

            if not isinstance(fixity_info, list):
                raise ValueError("Fixity information for algorithm must be a list")

            for info in fixity_info:
                if not isinstance(info, dict):
                    raise ValueError("Fixity information for algorithm must be a dictionary")

                filepath = info.get("filepath")
                if not isinstance(filepath, str):
                    raise ValueError("File path must be a string")

                if not filepath.startswith("data/objects/") or not filepath.endswith(".data"):
                    raise ValueError("File path must start with 'data/objects/' and end with '.data'")

                if not os.path.exists(filepath):
                    raise ValueError("File path does not exist")

                digest = info.get("digest")
                if not isinstance(digest, str):
                    raise ValueError("Digest must be a string")

                if digest not in manifest_files:
                    raise ValueError("Digest for file {filepath} is not in the manifest")

        # Check that all manifest files have a fixity entry
        for filepath in manifest_files:
            if not any(info.get("filepath") == filepath for info in fixity[algorithm]):
                raise ValueError("File {filepath} is in the manifest but has no fixity entry")

