def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate implements the interface
    if not hasattr(candidate, iface):
        raise RuntimeError("Candidate class does not implement the interface")

    # Check if the candidate's implementation satisfies the interface
    for method in iface._methods:
        if not hasattr(candidate, method):
            raise RuntimeError(f"Candidate class does not implement {method} method")

        candidate_method = getattr(candidate, method)
        iface_method = getattr(iface, method)

        if not tentative:
            # In strict mode, we check that the candidate's method has the same signature as the interface's method
            if signature(candidate_method) != signature(iface_method):
                raise RuntimeError(f"{method} method in candidate class has the wrong signature")
        else:
            # In tentative mode, we check that the candidate's method is a superset of the interface's method
            if not is_subset(signature(candidate_method), signature(iface_method)):
                raise RuntimeError(f"{method} method in candidate class is not a superset of the interface's method")

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    mcs = [mc for b in bases if isinstance(b, type) for mc in b.__mro__]
    if explicit_mc is not None:
        mcs.append(explicit_mc)
    meta = next(iter(mcs), type)
    for mc in mcs:
        if issubclass(mc, meta):
            meta = mc
            break
    return meta
