def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    # Legacy payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "type" in data and data["type"] == "PUBLIC_JSON":
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Check if the request is a matrix request
    if not request.META.get('MATRIX_ENCRYPTED', False):
        return False

    # Check if the request is a valid Matrix request
    try:
        # Try to unbox the matrix request
        json_request = json.loads(request.body)
        if not json_request.get('matrix'):
            return False
    except (TypeError, JSONDecodeError):
        return False

    return True

